class BinaryDataProcessor:
    """
    This is a class used to process binary data, which includes functions such as clearing non 0 or 1 characters, counting binary string information, and converting to corresponding strings based on different encoding methods.
    """

    def __init__(self, binary_string):
        """
        Initialize the class with a binary string and clean it by removing all non 0 or 1 characters.
        """
        self.binary_string = binary_string if binary_string is not None else ""
        self.clean_non_binary_chars()

    def clean_non_binary_chars(self):
        """
        Clean the binary string by removing all non 0 or 1 characters.
        >>> bdp = BinaryDataProcessor("01101000daf3e4r01100101011011000110110001101111")
        >>> bdp.clean_non_binary_chars()
        >>> bdp.binary_string
        '0110100001100101011011000110110001101111'
        """
        if self.binary_string is None:
            self.binary_string = ""
        else:
            self.binary_string = ''.join(c for c in self.binary_string if c in ('0', '1'))

    def calculate_binary_info(self):
        """
        Calculate the binary string information, including the percentage of 0 and 1, and the total length of the binary string.
        >>> bdp = BinaryDataProcessor("0110100001100101011011000110110001101111")
        >>> bdp.calculate_binary_info()
        {'Zeroes': 0.475, 'Ones': 0.525, 'Bit length': 40}
        """
        s = self.binary_string
        length = len(s)
        if length == 0:
            return {'Zeroes': 0.0, 'Ones': 0.0, 'Bit length': 0}
        zeroes = s.count('0')
        ones = s.count('1')
        zero_pct = round(zeroes / length, 3)
        one_pct = round(ones / length, 3)
        return {'Zeroes': zero_pct, 'Ones': one_pct, 'Bit length': length}

    def convert_to_ascii(self):
        """
        Convert the binary string to ascii string.
        >>> bdp = BinaryDataProcessor("0110100001100101011011000110110001101111")
        >>> bdp.convert_to_ascii()
        'hello'
        """
        s = self.binary_string
        if not s:
            return ''
        # ASCII: 8 bits per character
        chars = []
        for i in range(0, len(s), 8):
            byte = s[i:i+8]
            if len(byte) < 8:
                break  # Ignore incomplete byte
            val = int(byte, 2)
            try:
                chars.append(chr(val))
            except ValueError:
                # Out of ASCII range
                chars.append('?')
        return ''.join(chars)

    def convert_to_utf8(self):
        """
        Convert the binary string to utf-8 string.
        >>> bdp = BinaryDataProcessor("0110100001100101011011000110110001101111")
        >>> bdp.convert_to_utf8()
        'hello'
        """
        s = self.binary_string
        if not s:
            return ''
        # UTF-8: 8 bits per byte
        bytes_list = []
        for i in range(0, len(s), 8):
            byte = s[i:i+8]
            if len(byte) < 8:
                break  # Ignore incomplete byte
            bytes_list.append(int(byte, 2))
        try:
            return bytes(bytes_list).decode('utf-8')
        except UnicodeDecodeError:
            # If decoding fails, fallback to ASCII conversion
            return self.convert_to_ascii()

